  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 After Rome: Feudalism, the Manor and the Church$j$, $j${"readings": [{"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "In 410 the Visigoths sacked Rome, and in 476 the last Western emperor was removed. The fall of the West had deep effects. Strong central government faded, cities shrank, trade slowed, roads decayed and Germanic kingdoms, such as the Franks, took over former Roman lands. Frankish king Clovis became Christian around 496. The Church became the one common institution across the West.\n\nDanger from raiders such as Vikings, Magyars and Muslims led to feudalism, a system of land and loyalty. The king granted land, called a fief, to great lords. Lords gave land to knights in exchange for military service. A vassal swore loyalty to his lord. Most people were peasants, and many were serfs who worked the lord's manor, a farming estate, and could not leave it. The manor gave them protection, and they gave labor.\n\nThe Church shaped every part of life. Priests served villages, bishops oversaw regions and the Pope led the Western Church. Monasteries were centers of prayer, farming, schooling and care for the poor. Benedict of Nursia wrote a rule around 529 that guided monks by prayer and work. Monks copied books by hand, saving ancient and Christian writings. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nYour task: (1) Name two effects of the fall of Western Rome. (2) Draw a pyramid of the feudal hierarchy. (3) Tell two contributions of monasteries.\n\nFlorida standards: SS.912.W.2.9, SS.912.W.2.10, SS.912.W.2.12.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.2.9, SS.912.W.2.10, SS.912.W.2.12", "script": "Welcome to Unit 3. Listen, in four ten the Visigoths sacked Rome, and in four seventy six the last Western emperor was removed. The effects were deep. Strong central government faded. Cities shrank. Trade slowed. Roads decayed. Germanic kingdoms, such as the Franks, took over old Roman lands, and the Frankish king Clovis became a Christian around four ninety six. The Church became the one common institution across the West.\n\nNow watch this. Raiders such as the Vikings, the Magyars and others pressed in, and people turned to feudalism, a system of land and loyalty. A king granted land, called a fief, to great lords. Lords gave land to knights in return for military service. A vassal swore loyalty to his lord. Most people were peasants, and many were serfs who worked on the lord's manor, a farming estate. The manor gave protection, and the serf gave labor.\n\nLook at this. The Church shaped every part of life. Priests served villages, bishops oversaw regions, and the Pope led the Western Church. Monasteries were centers of prayer, farming, teaching and care for the poor. Benedict of Nursia wrote a rule around five twenty nine to guide monks by prayer and work. Monks copied books by hand and saved ancient and Christian writings. Colossians three and twenty three says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nYour task today. Name two effects of the fall of Rome. Draw the feudal pyramid. And tell two contributions of monasteries. Take the four question check when you finish.\n\nFaithful work in hidden places can preserve a civilization. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 After Rome: Feudalism, the Manor and the Church$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Kings, Law and the Rise of Towns$j$, $j${"readings": [{"title": "Isaiah 33 (King James Version)", "url": "/portal/bible/Isaiah/33"}], "body": "Medieval civilization blended three heritages: Greek and Roman learning and law, the Judeo Christian faith, and the customs of Germanic and northern European peoples, such as loyalty to a leader and local assemblies.\n\nStrong rulers rose. Charlemagne, king of the Franks, was crowned emperor by Pope Leo III on Christmas Day in 800. He built schools and encouraged learning in what is called the Carolingian Renaissance. Alfred the Great defended England from the Danes. William of Normandy won the Battle of Hastings in 1066 and became king of England. Thomas Aquinas, a scholar, joined faith and reason in his Summa Theologica.\n\nEnglish law grew in steps. Henry II sent traveling judges, and a system of common law and trial by jury grew. In 1215 the barons forced King John to sign the Magna Carta at Runnymede. It said that even the king was under the law and that free men could not be punished except by lawful judgment. Later Parliament grew into a body that approved taxes. Isaiah 33:22 says, For the LORD is our judge, the LORD is our lawgiver, the LORD is our king; he will save us.\n\nEconomic life changed too. Better plows, farming, growing population, markets, fairs, guilds of craftsmen, banking, trade routes and the rise of towns and universities set the base of the modern economy.\n\nYour task: (1) Tell what Charlemagne did in 800. (2) Explain why the Magna Carta mattered. (3) Name two factors in the growth of towns and trade.\n\nFlorida standards: SS.912.W.2.11, SS.912.W.2.13, SS.912.W.2.15, SS.912.W.2.17, SS.912.W.2.18.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.2.11, SS.912.W.2.13, SS.912.W.2.15, SS.912.W.2.17, SS.912.W.2.18", "script": "Welcome back. Listen, medieval civilization blended three heritages. Greek and Roman learning and law. The Judeo Christian faith. And the customs of Germanic and northern European peoples, such as loyalty to a leader and local assemblies.\n\nNow watch this. Strong rulers rose. Charlemagne, king of the Franks, was crowned emperor by Pope Leo the Third on Christmas Day in the year eight hundred. He built schools and encouraged learning in what we call the Carolingian Renaissance. Alfred the Great defended England from the Danes. William of Normandy won the Battle of Hastings in ten sixty six and became king of England. And Thomas Aquinas wrote the Summa Theologica, joining faith and reason.\n\nLook at this. English law grew step by step. Henry the Second sent traveling judges, and common law and trial by jury developed. In twelve fifteen the barons forced King John to sign the Magna Carta at Runnymede. It taught that even the king is under the law and that free men could not be punished except by lawful judgment. Later, Parliament grew into a body that approved taxes. Isaiah thirty three and twenty two says, For the LORD is our judge, the LORD is our lawgiver, the LORD is our king; he will save us.\n\nLife changed in the economy too. Better plows, a growing population, markets and fairs, craft guilds, banking, trade routes, towns and universities built the base of the modern economy.\n\nYour task today. Tell what Charlemagne did in eight hundred. Explain why the Magna Carta mattered. And name two factors in the growth of trade. Take the four question check.\n\nLaw under God protects the people. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Kings, Law and the Rise of Towns$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 The Crusades and the Crises of the Late Middle Ages$j$, $j${"readings": [{"title": "Psalm 46 (King James Version)", "url": "/portal/bible/Psalms/46"}], "body": "In 1095 Pope Urban II called at Clermont for a Crusade to help the Byzantine Empire and to win the Holy Land. The First Crusade took Jerusalem in 1099. In 1187 the Muslim leader Saladin retook the city. The Third Crusade, with Richard the Lionheart of England, Philip II of France and Frederick Barbarossa, did not retake Jerusalem but won a truce in 1192. In 1204 the Fourth Crusade turned against Constantinople and sacked it. Crusaders also attacked Jewish communities in the Rhineland, a grievous wrong. Effects of the Crusades included more trade with the East, the exchange of ideas, stronger kings and lasting mistrust.\n\nThe late Middle Ages brought crises:\nThe Great Famine of about 1315 to 1322, after heavy rains ruined crops.\nThe Black Death of 1347 to 1351, a plague that killed perhaps a third or more of Europe's people.\nThe Great Schism of the Western Church from 1378 to 1417, when rival popes claimed authority.\nThe Hundred Years War, 1337 to 1453, between England and France, where Joan of Arc rallied the French.\n\nThese events weakened feudalism and strengthened national identity. France under its kings, England with its Parliament, and Spain under Ferdinand and Isabella grew into stronger nations. Granada, the last Muslim stronghold in Spain, fell in 1492. Psalm 46:1 says, God is our refuge and strength, a very present help in trouble.\n\nYour task: (1) Name the leaders of the First and the Third Crusades. (2) List two effects of the Crusades. (3) Explain how the Black Death changed Europe.\n\nFlorida standards: SS.912.W.3.7, SS.912.W.3.8, SS.912.W.2.14, SS.912.W.2.16.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.3.7, SS.912.W.3.8, SS.912.W.2.14, SS.912.W.2.16", "script": "Welcome back. Listen, in ten ninety five Pope Urban the Second called at Clermont for a Crusade to help the Byzantine Empire and to win the Holy Land. The First Crusade took Jerusalem in ten ninety nine. In eleven eighty seven the Muslim leader Saladin retook the city. The Third Crusade, with Richard the Lionheart of England, Philip the Second of France and Frederick Barbarossa, did not retake Jerusalem but won a truce in eleven ninety two. In twelve oh four the Fourth Crusade turned against Constantinople and sacked a Christian city. Crusaders also attacked Jewish communities in the Rhineland, and that was a grievous wrong. The Crusades brought more trade with the East, an exchange of ideas, stronger kings and lasting mistrust.\n\nNow watch this. The late Middle Ages brought crisis after crisis. The Great Famine, about thirteen fifteen to thirteen twenty two, when rain ruined the crops. The Black Death, thirteen forty seven to thirteen fifty one, a plague that killed perhaps a third or more of Europe. The Great Schism, thirteen seventy eight to fourteen seventeen, when rival popes claimed authority. And the Hundred Years War, thirteen thirty seven to fourteen fifty three, between England and France, where Joan of Arc rallied the French.\n\nLook at this. These events weakened feudalism and strengthened nations. France grew under its kings, England with its Parliament, and Spain under Ferdinand and Isabella, who took Granada in fourteen ninety two. Psalm forty six and one says, God is our refuge and strength, a very present help in trouble.\n\nYour task today. Name the leaders of the First and Third Crusades. List two effects of the Crusades. And explain how the Black Death changed Europe. Take the four question check.\n\nIn every crisis, God is our help. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 The Crusades and the Crises of the Late Middle Ages$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Feudal Japan: Emperors, Shoguns and Samurai$j$, $j${"readings": [{"title": "Proverbs 14 (King James Version)", "url": "/portal/bible/Proverbs/14"}], "body": "While Europe built its feudal society, Japan grew a feudal system of its own. Japan is a chain of islands with mountains, which divided its people into clans. Early Japan borrowed writing, Buddhism and government ideas from China, while keeping its native Shinto beliefs about the spirits, called kami.\n\nIn 794 the capital moved to Heian, now Kyoto. The Heian period was a time of court culture. Lady Murasaki Shikibu wrote The Tale of Genji, often called the first novel. But powerful families and clans grew stronger than the emperor. In 1185 the Minamoto clan won a war, and in 1192 Minamoto no Yoritomo became shogun, a military ruler, setting up the Kamakura shogunate. The emperor remained a symbol, but the shogun held real power.\n\nThe shogun gave land to regional lords called daimyo. Daimyo kept warriors called samurai, who followed a code of honor called bushido, stressing loyalty, courage and discipline. Peasants farmed, and merchants ranked lower.\n\nMongol fleets tried to invade Japan in 1274 and 1281 but were defeated, helped by storms the Japanese later called divine winds, or kamikaze. Later the shogun's power weakened and clans fought in a long civil conflict until Tokugawa Ieyasu unified Japan in 1603.\n\nCompare Japan with Europe. Both had lords, warriors and peasants bound by oaths of loyalty. Japan, though, had a shogun ruling in the name of an emperor. Proverbs 14:34 says, Righteousness exalteth a nation: but sin is a reproach to any people.\n\nYour task: (1) Define shogun, daimyo and samurai. (2) Tell two ways Japan's feudalism was like Europe's and one way it differed. (3) Explain what happened to the Mongols in 1274 and 1281.\n\nFlorida standards: SS.912.W.2.19, SS.912.W.2.20, SS.912.W.2.21, SS.912.W.2.22.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.2.19, SS.912.W.2.20, SS.912.W.2.21, SS.912.W.2.22", "script": "Welcome back. Listen, while Europe built its feudal society, Japan grew a feudal system of its own. Japan is a chain of islands with mountains, which divided its people into clans. Early Japan borrowed writing, Buddhism and ideas of government from China, while keeping its native Shinto beliefs about spirits called kami.\n\nNow watch this. In seven ninety four the capital moved to Heian, which is now Kyoto. It was a time of court culture, and Lady Murasaki Shikibu wrote The Tale of Genji, often called the first novel. But powerful clans grew stronger than the emperor. In eleven eighty five the Minamoto clan won a war, and in eleven ninety two Minamoto no Yoritomo became shogun, a military ruler. The emperor stayed as a symbol, but the shogun held real power.\n\nLook at this. The shogun gave land to regional lords called daimyo. Daimyo kept warriors called samurai, who followed a code of honor called bushido, stressing loyalty, courage and discipline. Peasants farmed, and merchants ranked lower.\n\nMongol fleets tried to invade in twelve seventy four and twelve eighty one, and both attempts failed, helped by storms the Japanese called divine winds. In sixteen oh three Tokugawa Ieyasu united the country.\n\nCompare Japan and Europe. Both had lords, warriors and peasants bound by loyalty. But Japan had a shogun ruling in the name of an emperor. Proverbs fourteen and thirty four says, Righteousness exalteth a nation: but sin is a reproach to any people.\n\nYour task today. Define shogun, daimyo and samurai. Compare Japan and Europe. And explain what happened to the Mongols. Take the four question check.\n\nHonor and righteousness lift a people. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Feudal Japan: Emperors, Shoguns and Samurai$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Medieval Europe and Japan Comparison$j$, $j${"prompt": "Write a clear comparison of feudal Europe and feudal Japan, and add a short section about the Crusades. Use complete sentences and label each part. Proverbs 14:34 says, Righteousness exalteth a nation: but sin is a reproach to any people.\n\nPart 1: Explain how the fall of Western Rome led to feudalism in Europe.\nPart 2: Draw and explain the feudal pyramids of Europe and Japan, naming at least four levels in each.\nPart 3: Describe the role of the Church and of monasteries in medieval Europe.\nPart 4: Explain two English legal developments, including the Magna Carta, and why they matter today.\nPart 5: Explain two causes and two effects of the Crusades, and show fairness to the different sides.\nPart 6: Describe how crises such as the Black Death and the Hundred Years War changed Europe and helped form national identity in England, France or Spain.", "rubric": "70 points. Fall of Rome and feudalism: 8 points. Feudal pyramids compared: 14 points. Church and monasteries: 8 points. English legal developments: 10 points. Crusades causes and effects: 12 points. Crises and national identity: 14 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Medieval Europe and Japan Comparison$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Law, Loyalty and the Church$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains how the Magna Carta limited the power of a king, (2) tells how monasteries served both faith and learning, (3) compares the loyalty of a European vassal with that of a Japanese samurai, and (4) connects your answer to Isaiah 33:22, which says, For the LORD is our judge, the LORD is our lawgiver, the LORD is our king; he will save us. Then write a respectful reply of at least 40 words to another student, or answer this question: Why do you think the Crusades left such lasting mistrust? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Law, Loyalty and the Church$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: After Rome: Feudalism, the Manor and the Church$j$, $j${"questions": [{"q": "The feudal system was based on:", "options": ["Paper money", "Land in exchange for loyalty and service", "Printed books", "Elections"]}, {"q": "A serf was a peasant who:", "options": ["Ruled a kingdom", "Led monks", "Worked the lord's manor and could not leave it", "Was a knight"]}, {"q": "Monks helped preserve learning by:", "options": ["Burning libraries", "Leading armies", "Copying books by hand", "Selling land"]}, {"q": "A major effect of the fall of Western Rome was:", "options": ["Faster trade", "A single strong empire in Europe", "Weaker central government and smaller cities", "The end of Christianity"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: After Rome: Feudalism, the Manor and the Church$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,2}'::int[], array[$j$Lords granted fiefs and received loyalty and service.$j$,$j$Serfs were tied to the manor.$j$,$j$Monasteries saved ancient and Christian writings.$j$,$j$Order and trade broke down and local rulers gained power.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: After Rome: Feudalism, the Manor and the Church$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Kings, Law and the Rise of Towns$j$, $j${"questions": [{"q": "Charlemagne was crowned emperor in:", "options": ["1215", "800", "1066", "476"]}, {"q": "The Magna Carta of 1215 established the idea that:", "options": ["The king is under the law", "Parliament is abolished", "Peasants rule", "The king is above all law"]}, {"q": "William of Normandy became king of England after the Battle of:", "options": ["Tours", "Hastings", "Runnymede", "Crecy"]}, {"q": "Which helped medieval towns and trade grow?", "options": ["The end of farming", "The fall of every road", "Closing universities", "Guilds, markets and banking"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Kings, Law and the Rise of Towns$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,3}'::int[], array[$j$Pope Leo III crowned him on Christmas Day in 800.$j$,$j$Even the king had to obey the law.$j$,$j$He won at Hastings in 1066.$j$,$j$Commerce, craft guilds and finance spurred growth.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Kings, Law and the Rise of Towns$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: The Crusades and the Crises of the Late Middle Ages$j$, $j${"questions": [{"q": "Pope Urban II called for the First Crusade in:", "options": ["800", "1347", "1095", "1492"]}, {"q": "Which leader retook Jerusalem for the Muslims in 1187?", "options": ["Saladin", "Mehmed II", "Justinian", "Charles Martel"]}, {"q": "The Black Death of 1347 to 1351 was a:", "options": ["Trade treaty", "Religious council", "Great war between England and Spain", "Plague that killed a large part of Europe"]}, {"q": "The Hundred Years War was fought between:", "options": ["Rome and Persia", "Spain and Portugal", "England and France", "Japan and China"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: The Crusades and the Crises of the Late Middle Ages$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,2}'::int[], array[$j$He spoke at Clermont in 1095.$j$,$j$Saladin defeated the Crusaders and recaptured Jerusalem.$j$,$j$The plague spread along trade routes and killed millions.$j$,$j$The war lasted from 1337 to 1453.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: The Crusades and the Crises of the Late Middle Ages$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Feudal Japan: Emperors, Shoguns and Samurai$j$, $j${"questions": [{"q": "A shogun in Japan was a:", "options": ["Military ruler who held real power", "Peasant farmer", "Buddhist monk", "Foreign king"]}, {"q": "The samurai followed a code of honor called:", "options": ["Hijra", "Magna Carta", "Bushido", "Shinto"]}, {"q": "The Tale of Genji was written by:", "options": ["Minamoto no Yoritomo", "Joan of Arc", "Saladin", "Lady Murasaki Shikibu"]}, {"q": "Mongol invasions of Japan in 1274 and 1281:", "options": ["Conquered Kyoto", "Ended Shinto", "Created the shogunate", "Failed, helped by storms"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Feudal Japan: Emperors, Shoguns and Samurai$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,3}'::int[], array[$j$The shogun ruled in the name of the emperor.$j$,$j$Bushido stressed loyalty, courage and discipline.$j$,$j$She wrote it in the Heian court.$j$,$j$Storms and Japanese defenses defeated the fleets.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Feudal Japan: Emperors, Shoguns and Samurai$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Medieval Europe, the Crusades and Medieval Japan$j$, $j${"questions": [{"q": "Feudalism in Europe developed mainly because of:", "options": ["A strong Roman Senate", "Invasions and weak central government", "Printing", "Railroads"]}, {"q": "In feudalism, a vassal:", "options": ["Led a guild", "Ruled the Church", "Swore loyalty to a lord", "Taught monks"]}, {"q": "Benedict of Nursia is known for:", "options": ["Writing the Magna Carta", "Writing a rule for monks", "Leading the First Crusade", "Founding Heian"]}, {"q": "Thomas Aquinas wrote the:", "options": ["Justinian Code", "Canon of Medicine", "Tale of Genji", "Summa Theologica"]}, {"q": "The Magna Carta was signed by:", "options": ["William the Conqueror", "King John", "Henry V", "Charlemagne"]}, {"q": "The Great Schism of the Western Church (1378 to 1417) involved:", "options": ["The Black Death only", "Mongol invasions", "Two Roman emperors", "Rival popes"]}, {"q": "Minamoto no Yoritomo became the first shogun of the:", "options": ["Ming dynasty", "Tokugawa shogunate", "Heian court", "Kamakura shogunate"]}, {"q": "Ferdinand and Isabella ruled:", "options": ["Spain", "Japan", "The Mongols", "Persia"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Medieval Europe, the Crusades and Medieval Japan$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,3,1,3,3,0}'::int[], array[$j$People needed local protection.$j$,$j$A vassal pledged service in return for land.$j$,$j$His rule guided monastic life with prayer and work.$j$,$j$Aquinas joined faith and reason.$j$,$j$The barons forced John to sign at Runnymede.$j$,$j$Rival claimants to the papacy divided Western Christians.$j$,$j$He took the title in 1192.$j$,$j$Their marriage helped unite Spain, and Granada fell in 1492.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Medieval Europe, the Crusades and Medieval Japan$j$ on conflict (item_id) do nothing;
